DECK_PRESETS={'fire':{'ignis':[2,3,4],'solaris':[0,1,4],'magmor':[0,2,3]},'air':{'aerion':[0,1,2],'sylphida':[0,1,2],'veyr':[0,1,2]}}

def catalog():
 cards=[]
 for mon,lst in ABILITIES.items():
  for i,(name,effect) in enumerate(lst):
   cards.append(dict(id=f'{mon}_a{i}',kind='ability',owner=mon,team=MONSTERS[mon]['team'],name=name,effect=effect,awakened=i>=5,ap=0 if 'Реакция:' in effect else 1))
 for team,lst in TERRAINS.items():
  for i,(name,effect) in enumerate(lst):
   cards.append(dict(id=f'{team}_t{i}',kind='terrain',owner=None,team=team,name=name,effect=effect,awakened=False,ap=1))
 for i,(name,effect,ap) in enumerate(NEUTRALS):
  cards.append(dict(id=f'neutral_a{i}',kind='ability',owner=None,team='neutral',name=name,effect=effect,awakened=False,ap=ap))
 return cards
CARDS={x['id']:x for x in catalog()}

def deck_for(team):
 deck=[]
 for m,indices in DECK_PRESETS[team].items():
  for j,i in enumerate(indices):
   deck.extend([f'{m}_a{i}']*(2 if j<2 else 1))
 deck += [f'{team}_t{i}' for i in range(6)]
 assert len(deck)==21
 return deck
